mapper.update:
UPDATE games.garden_plot
SET prepared = 1
WHERE id = #{id}
  AND family_id = #{familyId}
  AND prepared = 0

UPDATE games.garden_plot
SET last_watered_at    = #{now},
    water_count        = water_count + 1,
    care_boost_minutes = care_boost_minutes + #{boost}
WHERE id = #{id}
  AND family_id = #{familyId}
  AND crop_code IS NOT NULL
  AND (last_watered_at IS NULL OR last_watered_at < #{boundary})

UPDATE games.garden_plot
SET last_sun_at        = #{now},
    sun_count          = sun_count + 1,
    care_boost_minutes = care_boost_minutes + #{boost}
WHERE id = #{id}
  AND family_id = #{familyId}
  AND crop_code IS NOT NULL
  AND (last_sun_at IS NULL OR last_sun_at < #{boundary})

UPDATE games.garden_plot
SET last_fertilized_at = #{now},
    fertilize_count    = fertilize_count + 1,
    care_boost_minutes = care_boost_minutes + #{boost}
WHERE id = #{id}
  AND family_id = #{familyId}
  AND crop_code IS NOT NULL
  AND (last_fertilized_at IS NULL OR last_fertilized_at < #{boundary})

UPDATE games.garden_plot
SET last_care_date = #{today}
WHERE id = #{id}
  AND family_id = #{familyId}
  AND (last_care_date IS NULL OR last_care_date < #{today})
